{
    "action": "create",
    "script_name": "test_smoke_XXX_login_password_empty.py",
    "summary": "新增登录时密码为空显示错误提示的冒烟测试用例",
    "script": "from playwright.sync_api import expect, Page\n\n\ndef test_login_password_empty_show_error(page: Page, base_url: str):\n    # 访问登录页面\n    page.goto(f\"{base_url}/login\")\n    # 输入用户名，密码留空\n    page.locator('#username').fill('admin')\n    # 点击登录按钮\n    page.locator('#login-btn').click()\n    # 断言错误提示区域可见\n    expect(page.locator('#login-error')).to_be_visible()\n    # 断言页面未跳转，仍在登录页\n    expect(page).to_have_url(f\"{base_url}/login\")",
    "cases": [
        {
            "func": "test_login_password_empty_show_error",
            "title": "登录时密码为空显示相应错误提示",
            "precondition": "1. 处于未登录状态；2. 可正常访问被测电商网站",
            "steps": "1. 访问登录页面 /login；2. 在用户名输入框输入演示账号用户名 admin，密码输入框保持为空；3. 点击登录按钮",
            "expected": "1. 页面停留在登录页，未发生跳转；2. 登录错误提示区域 #login-error 可见，显示密码为空的相关错误提示"
        }
    ]
}

{
    "action": "update",
    "script_name": "test_smoke_004_login_password_empty.py",
    "summary": "修复登录密码为空用例的断言错误：因密码输入框带有required必填属性，空密码提交会被浏览器原生校验拦截，服务端#login-error元素不会渲染，改为断言密码输入框处于:invalid状态且页面未跳转",
    "script": "from playwright.sync_api import expect, Page\n\n\ndef test_login_password_empty_show_error(page: Page, base_url: str):\n    # 访问登录页面\n    page.goto(f\"{base_url}/login\")\n    # 输入用户名，密码留空\n    page.locator('#username').fill('admin')\n    # 点击登录按钮\n    page.locator('#login-btn').click()\n    # 断言密码输入框触发原生必填校验，处于invalid状态\n    expect(page.locator(\"#password:invalid\")).to_be_visible()\n    # 断言页面未跳转，仍在登录页\n    expect(page).to_have_url(f\"{base_url}/login\")",
    "cases": [
        {
            "func": "test_login_password_empty_show_error",
            "title": "登录时密码为空触发浏览器原生必填校验，页面不跳转",
            "precondition": "1. 处于未登录状态；2. 可正常访问被测电商网站",
            "steps": "1. 访问登录页面 /login；2. 在用户名输入框输入演示账号用户名 admin，密码输入框保持为空；3. 点击登录按钮",
            "expected": "1. 密码输入框触发浏览器原生必填校验，处于:invalid状态；2. 页面停留在登录页，未发生跳转"
        }
    ]
}
